# timing: geometric mean of views / channel median per day and 3-hour block (ET), divided by the overall average -> "1.05 = 5% above average"
_DAY = {'Monday': (1.112, 3422), 'Tuesday': (1.039, 3028), 'Wednesday': (1.045, 3400), 'Thursday': (1.039, 3107), 'Friday': (1.047, 4012), 'Saturday': (1.094, 4185), 'Sunday': (1.083, 3764)}   # everything analysis/data/timing_geo.json
_HOUR = {'12–3 AM': 1.042, '3–6 AM': 1.037, '6–9 AM': 1.103, '9 AM–12 PM': 1.083, '12–3 PM': 1.051, '3–6 PM': 1.053, '6–9 PM': 1.069, '9 PM–12 AM': 1.049}
_avg = sum(v * n for v, n in _DAY.values()) / sum(n for _, n in _DAY.values())
DAY_ROWS = [(d, round(v / _avg, 3)) for d, (v, n) in _DAY.items()]
HOUR_ROWS = [(h, round(v / (sum(_HOUR.values()) / len(_HOUR)), 3)) for h, v in _HOUR.items()]

